<?php use function Studio\{e,url,size_label,storage,config,thai_date,status_label}; $title='ภาพรวม'; $used=storage()->usedBytes(); $budget=(int)config('storage_budget_bytes'); $pct=$budget>0?min(100,$used/$budget*100):0; ?>
