<div class="stats-grid"><?php foreach ([['คอนเทนต์ทั้งหมด',$counts['total'],'รายการในพื้นที่ทำงาน'],['ร่าง',$counts['drafts']??0,'กำลังเตรียมเนื้อหา'],['รออนุมัติ',$counts['reviews']??0,'พร้อมให้ตรวจสอบ'],['รอโพสต์ส่วนตัว',$waiting,'หลังอนุมัติคอนเทนต์']] as [$label,$value,$note]): ?><div class="stat"><div class="stat-label"><?= e($label) ?></div><div class="stat-value"><?= e($value) ?></div><div class="stat-note"><?= e($note) ?></div></div><?php endforeach; ?></div>
<div class="dashboard-columns"><section class="panel"><div class="section-heading"><div><h2>คอนเทนต์ล่าสุด</h2><p>งานที่คุณกำลังเตรียมและตรวจอนุมัติ</p></div><a href="<?= e(url('contents')) ?>">ดูทั้งหมด →</a></div><?php if(!$recent): ?><div class="empty-state"><div class="empty-symbol">+</div><h3>เริ่มจากคลิปแรกของคุณ</h3><p>อัปโหลด MP4 แนวตั้ง 30–60 วินาที แล้วเตรียมข้อความแยกช่องทาง</p><a class="btn btn-outline-primary" href="<?= e(url('library')) ?>">เพิ่มวิดีโอเข้าคลัง</a></div><?php else: foreach($recent as $c): ?><a class="content-row" href="<?= e(url('content',['id'=>$c['id']])) ?>"><div class="content-number"><?= e(str_pad((string)$c['id'],2,'0',STR_PAD_LEFT)) ?></div><div class="flex-grow-1"><strong><?= e($c['title_internal']) ?></strong><small>แก้ไข <?= e(thai_date($c['updated_at'])) ?></small></div><span class="badge badge-soft"><?= e(status_label($c['status'])) ?></span><span>→</span></a><?php endforeach; endif; ?></section>
<div><section class="panel storage-panel"><div class="eyebrow">MEDIA STORAGE</div><h2>พื้นที่คลังวิดีโอ</h2><div class="storage-value"><?= e(size_label($used)) ?><small> / <?= e(size_label($budget)) ?></small></div><progress value="<?= e($pct) ?>" max="100" class="storage-progress">พื้นที่ใช้งาน</progress><p class="small text-secondary mt-3">วงเงินของแอป ไม่ใช่ค่าพื้นที่คงเหลือจริงจากบัญชีโฮสติ้ง · ไม่มีการลบไฟล์อัตโนมัติ</p><?php if($pct>=80): ?><div class="alert alert-warning">พื้นที่คลังใกล้ถึงวงเงิน กรุณาสำรองและวางแผนย้ายไฟล์</div><?php endif; ?><a href="<?= e(url('settings')) ?>">ดูรายละเอียดระบบ →</a></section><section class="next-step"><span class="eyebrow">NEXT STEP</span><h3>เตรียมปลายทางของคุณ</h3><p>เพิ่มรายการเพจและช่อง เพื่อเลือกปลายทางในคอนเทนต์ ก่อนเชื่อม API ใน Phase 2</p><a href="<?= e(url('accounts')) ?>">เพิ่มเพจ / ช่อง →</a></section></div></div>
